From 2e31185a56a68e9d0f7c77e4e393a5ea7840b9b3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 13:18:50 +0100
Subject: [PATCH] ksldapp: don't let an early SIGUSR1 kill a starting greeter

Locking twice in a row sent SIGUSR1 to a greeter that had not set up its
handler yet, which killed it and restarted it with software rendering,
so the lock screen lost its blur. Start it with SIGUSR1 blocked instead.

BUG: 475142
---
 ksldapp.cpp | 7 +++++++
 1 file changed, 7 insertions(+)

diff --git a/ksldapp.cpp b/ksldapp.cpp
index 2e83b2ac..9307a231 100644
--- a/ksldapp.cpp
+++ b/ksldapp.cpp
@@ -158,6 +158,13 @@ void KSldApp::initialize()
     m_lockProcess = new QProcess();
     m_lockProcess->setProcessChannelMode(QProcess::ForwardedErrorChannel);
     m_lockProcess->setReadChannel(QProcess::StandardOutput);
+    m_lockProcess->setChildProcessModifier([] {
+        // keep SIGUSR1 pending until the greeter has set up its handler
+        sigset_t blockedSignals;
+        sigemptyset(&blockedSignals);
+        sigaddset(&blockedSignals, SIGUSR1);
+        pthread_sigmask(SIG_BLOCK, &blockedSignals, nullptr);
+    });
     auto finishedSignal = static_cast<void (QProcess::*)(int, QProcess::ExitStatus)>(&QProcess::finished);
     connect(m_lockProcess, &QProcess::readyRead, this, [this] {
         const auto str = QString::fromLocal8Bit(m_lockProcess->readLine());
